CREATE TYPE "UserRole" AS ENUM ('ADMIN', 'STAFF');
CREATE TYPE "UserStatus" AS ENUM ('PENDING', 'ACTIVE', 'DISABLED');
CREATE TYPE "OfferStatus" AS ENUM ('DRAFT', 'PUBLISHED', 'ARCHIVED');
CREATE TYPE "OfferType" AS ENUM ('GENERAL', 'HOTEL');
CREATE TYPE "ReservationStatus" AS ENUM ('PENDING', 'CONTACTED', 'CONFIRMED', 'CANCELLED', 'COMPLETED');

CREATE TABLE "User" ("id" TEXT NOT NULL, "email" TEXT NOT NULL, "passwordHash" TEXT NOT NULL, "firstName" TEXT NOT NULL, "lastName" TEXT NOT NULL, "role" "UserRole" NOT NULL DEFAULT 'STAFF', "status" "UserStatus" NOT NULL DEFAULT 'PENDING', "emailVerifiedAt" TIMESTAMP(3), "lastLoginAt" TIMESTAMP(3), "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "User_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "User_email_key" ON "User"("email");
CREATE TABLE "Session" ("id" TEXT NOT NULL, "tokenHash" TEXT NOT NULL, "userId" TEXT NOT NULL, "expiresAt" TIMESTAMP(3) NOT NULL, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "lastUsedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "Session_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "Session_tokenHash_key" ON "Session"("tokenHash"); CREATE INDEX "Session_userId_expiresAt_idx" ON "Session"("userId", "expiresAt");
CREATE TABLE "EmailToken" ("id" TEXT NOT NULL, "tokenHash" TEXT NOT NULL, "userId" TEXT NOT NULL, "type" TEXT NOT NULL, "expiresAt" TIMESTAMP(3) NOT NULL, "usedAt" TIMESTAMP(3), "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "EmailToken_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "EmailToken_tokenHash_key" ON "EmailToken"("tokenHash"); CREATE INDEX "EmailToken_userId_type_expiresAt_idx" ON "EmailToken"("userId", "type", "expiresAt");
CREATE TABLE "offers" ("id" TEXT NOT NULL, "categoryId" TEXT NOT NULL, "code" TEXT NOT NULL, "type" "OfferType" NOT NULL DEFAULT 'GENERAL', "status" "OfferStatus" NOT NULL DEFAULT 'DRAFT', "price" DECIMAL(10,2) NOT NULL, "simplePriceTnd" DECIMAL(10,2), "halfBoardPriceTnd" DECIMAL(10,2), "fullBoardPriceTnd" DECIMAL(10,2), "softAllInclusivePriceTnd" DECIMAL(10,2), "hotelStars" INTEGER, "currency" TEXT NOT NULL DEFAULT 'TND', "durationMin" INTEGER, "coverImageUrl" TEXT, "sortOrder" INTEGER NOT NULL DEFAULT 0, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "offers_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "offers_code_key" ON "offers"("code"); CREATE INDEX "offers_categoryId_status_sortOrder_idx" ON "offers"("categoryId", "status", "sortOrder");
CREATE TABLE "offer_translations" ("id" TEXT NOT NULL, "offerId" TEXT NOT NULL, "locale" TEXT NOT NULL, "title" TEXT NOT NULL, "slug" TEXT NOT NULL, "shortDescription" TEXT, "description" TEXT, "terms" TEXT, "metaTitle" TEXT, "metaDescription" TEXT, CONSTRAINT "offer_translations_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "offer_translations_offerId_locale_key" ON "offer_translations"("offerId", "locale"); CREATE UNIQUE INDEX "offer_translations_locale_slug_key" ON "offer_translations"("locale", "slug");
CREATE TABLE "offer_images" ("id" TEXT NOT NULL, "offerId" TEXT NOT NULL, "url" TEXT NOT NULL, "thumbnailUrl" TEXT NOT NULL, "mediumUrl" TEXT NOT NULL, "largeUrl" TEXT NOT NULL, "altText" TEXT, "displayOrder" INTEGER NOT NULL DEFAULT 0, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "offer_images_pkey" PRIMARY KEY ("id"));
CREATE TABLE "reservations" ("id" TEXT NOT NULL, "offerId" TEXT NOT NULL, "customerName" TEXT NOT NULL, "customerEmail" TEXT, "customerPhone" TEXT NOT NULL, "bookingDate" TIMESTAMP(3) NOT NULL, "guests" INTEGER NOT NULL DEFAULT 1, "notes" TEXT, "status" "ReservationStatus" NOT NULL DEFAULT 'PENDING', "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "reservations_pkey" PRIMARY KEY ("id"));
CREATE INDEX "reservations_status_bookingDate_idx" ON "reservations"("status", "bookingDate");
CREATE TABLE "site_settings" ("id" TEXT NOT NULL, "key" TEXT NOT NULL, "value" TEXT NOT NULL, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "site_settings_pkey" PRIMARY KEY ("id")); CREATE UNIQUE INDEX "site_settings_key_key" ON "site_settings"("key");
CREATE TABLE "audit_logs" ("id" TEXT NOT NULL, "userId" TEXT, "action" TEXT NOT NULL, "entity" TEXT NOT NULL, "entityId" TEXT, "metadata" JSONB, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "audit_logs_pkey" PRIMARY KEY ("id")); CREATE INDEX "audit_logs_entity_entityId_createdAt_idx" ON "audit_logs"("entity", "entityId", "createdAt");
ALTER TABLE "category_translations" ADD CONSTRAINT "category_translations_locale_slug_key_check" CHECK (char_length("locale") > 0);
ALTER TABLE "Session" ADD CONSTRAINT "Session_userId_fkey" FOREIGN KEY ("userId") REFERENCES "User"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "EmailToken" ADD CONSTRAINT "EmailToken_userId_fkey" FOREIGN KEY ("userId") REFERENCES "User"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "offers" ADD CONSTRAINT "offers_categoryId_fkey" FOREIGN KEY ("categoryId") REFERENCES "categories"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE "offer_translations" ADD CONSTRAINT "offer_translations_offerId_fkey" FOREIGN KEY ("offerId") REFERENCES "offers"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "offer_images" ADD CONSTRAINT "offer_images_offerId_fkey" FOREIGN KEY ("offerId") REFERENCES "offers"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "reservations" ADD CONSTRAINT "reservations_offerId_fkey" FOREIGN KEY ("offerId") REFERENCES "offers"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE "audit_logs" ADD CONSTRAINT "audit_logs_userId_fkey" FOREIGN KEY ("userId") REFERENCES "User"("id") ON DELETE SET NULL ON UPDATE CASCADE;
